import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/attribute/commands.md","filePath":"en/modules/attribute/commands.md","lastUpdated":0}`),a={name:`en/modules/attribute/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to “Commands and Permissions”">​</a></h1><p>The main command of EmakiAttribute is <code>/emakiattribute</code>, with <code>/eattribute</code> and <code>/ea</code> as aliases. Players usually do not need to run these commands directly. Administrators use them to reload configuration, resync attributes, preview item contribution, dump combat state, and debug damage calculations.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to “Commands”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/ea help</code></td><td>none (gated by <code>emakiattribute.use</code>)</td><td>Print command help; running <code>/ea</code> with no arguments is equivalent.</td></tr><tr><td><code>/ea reload</code></td><td><code>emakiattribute.reload</code> or <code>emakiattribute.admin</code></td><td>Reload configuration, attributes, conditions, damage types, lore formats, and related registries.</td></tr><tr><td>\`/ea resync [player</td><td>all]\`</td><td><code>emakiattribute.resync</code> or <code>emakiattribute.admin</code></td></tr><tr><td><code>/ea preview [player] [slot]</code></td><td><code>emakiattribute.debug</code> or <code>emakiattribute.admin</code></td><td>Preview the attribute contribution of a specific equipment slot.</td></tr><tr><td><code>/ea dump [player] [sources [attribute]|json]</code></td><td><code>emakiattribute.debug</code> or <code>emakiattribute.admin</code></td><td>Dump a player&#39;s combat attribute snapshot and resource state; optionally add source tracing or JSON output.</td></tr><tr><td><code>/ea debug [player] [toggle/on/off]</code></td><td><code>emakiattribute.debug</code> or <code>emakiattribute.admin</code></td><td>Toggle or set combat debug output; also forwards <code>status</code>, <code>on</code>, <code>off</code>, <code>player</code>, and <code>module</code>.</td></tr><tr><td><code>/ea source &lt;player&gt; &lt;attribute&gt;</code></td><td><code>emakiattribute.debug</code> or <code>emakiattribute.admin</code></td><td>List each contribution to one attribute and whether its condition passed.</td></tr><tr><td><code>/ea trace last|list|export|clear &lt;player&gt;</code></td><td><code>emakiattribute.debug</code> or <code>emakiattribute.admin</code></td><td>Inspect, export, or clear a player&#39;s damage resolution trace records.</td></tr><tr><td><code>/ea points view/open/add/reset ...</code></td><td><code>emakiattribute.points</code> or <code>emakiattribute.admin</code></td><td>View points, open the GUI, allocate parent-attribute points, or reset your own allocation.</td></tr><tr><td><code>/ea points set/grant/setreset player amount</code></td><td><code>emakiattribute.points.admin</code> or <code>emakiattribute.admin</code></td><td>Set available points, grant points, or set reset points for a player.</td></tr><tr><td><code>/ea lint</code></td><td><code>emakiattribute.reload</code> or <code>emakiattribute.admin</code></td><td>Check configuration references, attribute ids, formats, damage types, and read conditions before reloading.</td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to “Permissions”">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>emakiattribute.use</code></td><td>true</td><td>Allows root command access.</td></tr><tr><td><code>emakiattribute.reload</code></td><td>op</td><td>Allows reload and lint.</td></tr><tr><td><code>emakiattribute.resync</code></td><td>op</td><td>Allows attribute resync.</td></tr><tr><td><code>emakiattribute.debug</code></td><td>op</td><td>Allows preview, dump, and debug output.</td></tr><tr><td><code>emakiattribute.points</code></td><td>true</td><td>Allows viewing points, opening the points GUI, allocating your own points, and paid self-reset.</td></tr><tr><td><code>emakiattribute.points.admin</code></td><td>op</td><td>Allows viewing/opening other players&#39; points, setting available points, granting points, setting reset points, and free resets.</td></tr><tr><td><code>emakiattribute.admin</code></td><td>op</td><td>Administrative fallback permission.</td></tr></tbody></table><h2 id="common-operations" tabindex="-1">Common operations <a class="header-anchor" href="#common-operations" aria-label="Permalink to “Common operations”">​</a></h2><h3 id="reload-after-linting" tabindex="-1">Reload after linting <a class="header-anchor" href="#reload-after-linting" aria-label="Permalink to “Reload after linting”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ea lint</span></span>
<span class="line"><span>/ea reload</span></span></code></pre></div><p>Run <code>lint</code> first after changing <code>attributes/</code>, <code>conditions/</code>, <code>damage_types/</code>, <code>lore_formats/</code>, presets, or PDC read rules. Then reload if no blocking issues are reported.</p><h3 id="resync-all-online-players" tabindex="-1">Resync all online players <a class="header-anchor" href="#resync-all-online-players" aria-label="Permalink to “Resync all online players”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ea resync all</span></span></code></pre></div><p>Use this after changing attribute definitions, default values, equipment parsing, or other rules that affect currently online players.</p><h3 id="preview-an-equipment-slot" tabindex="-1">Preview an equipment slot <a class="header-anchor" href="#preview-an-equipment-slot" aria-label="Permalink to “Preview an equipment slot”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ea preview Steve main_hand</span></span></code></pre></div><p>Common slots include:</p><ul><li><code>main_hand</code></li><li><code>off_hand</code></li><li><code>helmet</code></li><li><code>chestplate</code></li><li><code>leggings</code></li><li><code>boots</code></li></ul><p><code>preview</code> reads the item in the requested slot and shows its item snapshot, signature, and non-zero values.</p><h3 id="dump-combat-state" tabindex="-1">Dump combat state <a class="header-anchor" href="#dump-combat-state" aria-label="Permalink to “Dump combat state”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ea dump Steve</span></span></code></pre></div><p>Use this when a player&#39;s final combat attributes or resources do not match expectation. It prints the combat snapshot and resource states used by the runtime.</p><h3 id="trace-where-an-attribute-comes-from" tabindex="-1">Trace where an attribute comes from <a class="header-anchor" href="#trace-where-an-attribute-comes-from" aria-label="Permalink to “Trace where an attribute comes from”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ea source Steve physical_attack</span></span>
<span class="line"><span>/ea dump Steve sources physical_attack</span></span></code></pre></div><p>Lists each contribution value, source type, and source label for that attribute; contributions whose condition failed are marked. Omitting the attribute id in <code>/ea dump &lt;player&gt; sources</code> lists every attribute source, and <code>/ea dump &lt;player&gt; json</code> additionally prints the source trace as JSON.</p><h3 id="review-a-damage-resolution" tabindex="-1">Review a damage resolution <a class="header-anchor" href="#review-a-damage-resolution" aria-label="Permalink to “Review a damage resolution”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ea trace last Steve</span></span>
<span class="line"><span>/ea trace list Steve</span></span>
<span class="line"><span>/ea trace export Steve</span></span>
<span class="line"><span>/ea trace clear Steve</span></span></code></pre></div><p><code>last</code> prints the summary and per-stage input/output of the most recent hit, <code>list</code> prints recorded trace summaries, <code>export</code> prints the most recent record as JSON, and <code>clear</code> removes that player&#39;s records.</p><h3 id="open-the-points-gui-and-allocate-points" tabindex="-1">Open the points GUI and allocate points <a class="header-anchor" href="#open-the-points-gui-and-allocate-points" aria-label="Permalink to “Open the points GUI and allocate points”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ea points open</span></span>
<span class="line"><span>/ea points view</span></span>
<span class="line"><span>/ea points add strength 1</span></span></code></pre></div><p><code>points add</code> allocates your own available points into an attribute marked with <code>parent_attribute: true</code>. It fails when points are insufficient, the attribute ID does not exist, or the target is not a parent attribute. Console execution must provide a player target.</p><h3 id="grant-and-reset-attribute-points-as-admin" tabindex="-1">Grant and reset attribute points as admin <a class="header-anchor" href="#grant-and-reset-attribute-points-as-admin" aria-label="Permalink to “Grant and reset attribute points as admin”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ea points grant Steve 5</span></span>
<span class="line"><span>/ea points set Steve 10</span></span>
<span class="line"><span>/ea points setreset Steve 1</span></span>
<span class="line"><span>/ea points reset Steve free</span></span></code></pre></div><p><code>grant</code> adds available points, <code>set</code> replaces available points, and <code>setreset</code> sets how many paid resets the player has. Admin resets for another player, or resets with <code>free</code>, do not consume the player&#39;s reset points.</p><h3 id="enable-combat-debug-output" tabindex="-1">Enable combat debug output <a class="header-anchor" href="#enable-combat-debug-output" aria-label="Permalink to “Enable combat debug output”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ea debug Steve on</span></span>
<span class="line"><span>/ea debug Steve off</span></span></code></pre></div><p>Use debug output only while troubleshooting. Do not leave large-scale player debug enabled on production servers.</p>`,36)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};